import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"常见问题（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/faq.md","filePath":"appendix/faq.md","lastUpdated":null}'),n={name:"appendix/faq.md"};function s(p,t,d,i,q,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h1><h2 id="登录与安全" tabindex="-1">登录与安全 <a class="header-anchor" href="#登录与安全" aria-label="Permalink to &quot;登录与安全&quot;">​</a></h2><p><strong>Q：默认账号密码是什么？如何修改？</strong> 默认 <code>admin</code> / <code>123456</code>。通过环境变量 <code>NS_USER</code> / <code>NS_PWD</code> 修改，生产部署务必修改。</p><p><strong>Q：登录失败被锁定怎么办？</strong> 账户连续失败 3 次锁定；IP 失败 5 次冻结 1 小时，冻结期间再失败封禁 1 天。等待解锁或重启平台。</p><p><strong>Q：页面提示会话失效？</strong> 平台使用 Session + CSRF Token 机制，长时间未操作需重新登录。</p><h2 id="网关与账户" tabindex="-1">网关与账户 <a class="header-anchor" href="#网关与账户" aria-label="Permalink to &quot;网关与账户&quot;">​</a></h2><p><strong>Q：为什么&quot;新建网关&quot;按钮点不了 / 提示禁止操作？</strong> 演示模式（demo profile）下禁止创建、修改、删除网关与回测任务。</p><p><strong>Q：CTP 渠道在下拉里看不到？</strong> 本发行版只内置 PLAYBACK 与 SIM 渠道。CTP 等实盘网关由外部 jar 提供，需将网关 jar 放到程序 jar 同级目录后重启（启动脚本通过 <code>-Dloader.path</code> 加载）。CTP_SIM 渠道仅超级用户模式可见。</p><p><strong>Q：网关显示&quot;已断开&quot;？</strong> 点卡片&quot;连线&quot;手动重连；若开启了&quot;自动连线&quot;，平台会按渠道自身的重连机制处理。检查网络与网关配置中的凭据是否正确。</p><p><strong>Q：一个账户想同时跑多个策略可以吗？</strong> 可以。每个策略建一个模组，多个模组可绑定同一个交易账户；每个模组有独立的模组账户（分配金额）控制风险。</p><h2 id="历史回放" tabindex="-1">历史回放 <a class="header-anchor" href="#历史回放" aria-label="Permalink to &quot;历史回放&quot;">​</a></h2><p><strong>Q：回放数据从哪来？</strong> 来自平台数据服务（marketplace.quantit.tech），需保证服务器能访问外网且订阅有效（首页&quot;已购服务&quot;可查看订阅与到期日）。</p><p><strong>Q：预加载失败或很慢？</strong> 检查数据服务订阅是否到期；缩短回放区间、降低回放精度、减少订阅合约数量。</p><p><strong>Q：日期为什么选不了 2021 年之前？</strong> 回放数据最早支持 2021-01-01。</p><p><strong>Q：状态重置会丢失什么？</strong> 重置回放会同时重置所有&quot;回测&quot;用途的模组（清空模组账户与持仓），不影响模拟盘/实盘模组。</p><h2 id="模拟盘与交易" tabindex="-1">模拟盘与交易 <a class="header-anchor" href="#模拟盘与交易" aria-label="Permalink to &quot;模拟盘与交易&quot;">​</a></h2><p><strong>Q：SIM 账户的钱从哪来？</strong> 通过网关卡片&quot;更多 → 出入金&quot;注入虚拟资金，正数入金、负数出金。</p><p><strong>Q：为什么&quot;账户绩效&quot;按钮是灰的？</strong> 账户绩效与历史持仓线功能仅对 SIM 账户开放。</p><p><strong>Q：画线交易没反应？</strong> 先在交易面板选择交易账户，再在图表右键菜单使用画线交易。</p><h2 id="程序化交易" tabindex="-1">程序化交易 <a class="header-anchor" href="#程序化交易" aria-label="Permalink to &quot;程序化交易&quot;">​</a></h2><p><strong>Q：我的策略 jar 放哪？</strong> 放到程序 jar（<code>northstar-x.y.z.jar</code>）同级目录，重启平台后即可在模组&quot;绑定策略&quot;下拉中看到。</p><p><strong>Q：为什么策略下拉里看不到示例策略？</strong> 模组表单的&quot;显示示例策略&quot;复选框默认不勾选。</p><p><strong>Q：模组显示&quot;异常&quot;状态？</strong> 进入 <strong>日志中心 → 模组日志</strong> 查看该模组的错误日志定位原因；处理后可在模组管理中重置并重新启用。</p><p><strong>Q：修改模组为什么提示要先停用？</strong> 运行中（已启用）的模组不允许修改，先停用再修改；重新启用即生效。</p>',24)])])}const l=o(n,[["render",s]]);export{g as __pageData,l as default};
